pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        address actor,
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.depositorAccount());

        vm.prank(actor);
        try c.setL1BlockValues(
            number, timestamp, basefee, hash, sequenceNumber,
            batcherHash, l1FeeOverhead, l1FeeScalar
        ) {
            // unauthorized call should never succeed
            assertTrue(false, "unauthorized call succeeded");
        } catch {
            // rule: sequenceNumber stays at its initial value 0
            assertTrue(c.sequenceNumber() == 0, "sequenceNumber mutated by unauthorized caller");
        }
    }
}

