pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address actor,
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        // depositorAccount is uninitialized (address(0)); any other caller must be rejected
        vm.assume(actor != address(0));
        vm.assume(batcherHash != bytes32(0));

        vm.prank(actor);
        try c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar) {
            // a non-depositor call should never succeed; if it did, both versions accept —
            // the invariant below still holds since the caller IS authorized then
        } catch {
            // reverted: batcherHash must remain untouched (bytes32(0))
        }

        assertTrue(
            c.batcherHash() == bytes32(0),
            "failed/unauthorized setL1BlockValues must not modify batcherHash"
        );
    }
}

