// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 seq, bytes32 batcherHash, uint256 overhead, uint256 scalar) public {
        // WIDE domain: any actor (including the depositor address itself, which is 0 here),
        // any values; only require the payload to be distinguishable from the initial state.
        vm.assume(batcherHash != bytes32(0));
        vm.prank(actor);
        c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcherHash, overhead, scalar);
        // Reference: setL1BlockValues never mutates batcherHash for ANY caller/inputs.
        assertTrue(c.batcherHash() == bytes32(0));
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );
        assert(!ok);
    }
}

