contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(c.depositorAccount() != address(this));
        bool reverted; try c.setL1BlockValues(1, 2, 3, bytes32(0), 4, bytes32(0), 5, 6) { reverted = false; } catch { reverted = true; }   // boundary
