    constructor(C _c) { c = _c; }
    function run() public payable {
        bool reverted;
        try c.setL1BlockValues(1, 2, 3, bytes32(uint256(4)), 5, bytes32(uint256(6)), 7, 8) { reverted = false; } catch { reverted = true; }
        assert(reverted == (msg.sender != c.depositorAccount()));
    }
